/*****************
 *     Code      *
 *****************/

.cX-Code-Key {
  color: var(--cx-code-key, var(--cx-ui-code-key));
  font-weight: bold;
}

.cX-Code-Value,
.cX-Code-Number,
.cX-Code-Null {
  color: var(--cx-code-value, var(--cx-ui-code-value));
}

.cX-Code-String {
  color: var(--cx-code-string, var(--cx-ui-code-string));
}

.cX-Code-Boolean {
  color: var(--cx-code-boolean, var(--cx-ui-code-boolean));
}

.cX-Code-Comment {
  color: var(--cx-code-comment, var(--cx-ui-code-comment));
}

.cX-Container-Code {
  z-index: var(--cx-z-modal);
  background: transparent;
}

div.cX-Code {
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  background-color: var(--cx-ui-surface-sunken);
  color: var(--cx-font-color, var(--cx-ui-text));
  font: var(--cx-font);
  margin: 2px 3px;
  padding: 10px 20px 20px 10px;
  position: absolute;
  white-space: nowrap;
  overflow: hidden;
  z-index: var(--cx-z-panel);
}

.cX-Code-Container {
  clear: both;
  width: 600px;
  overflow: auto;
  background-color: var(--cx-ui-surface);
  position: relative;
  top: 10px;
}

.cX-Code-Toolbar {
  display: flex;
  flex-wrap: nowrap;
  overflow: hidden;
  justify-content: start;
}

.cX-Code-Icons {
  display: flex;
  position: relative;
  margin-left: auto;
  gap: 8px;
  align-items: center;
}

.cX-Code-Icons img,
.cX-Code-Icons svg {
  width: 24px;
  height: 24px;
}

.cX-Code-Error {
  height: 36px;
  width: 280px;
  float: left;
  clear: none;
  resize: none;
  top: 5px;
  left: 20px;
  background-color: var(--cx-ui-surface-sunken);
  overflow: hidden;
  white-space: nowrap;
  color: var(--cx-ui-danger);
  position: relative;
  cursor: pointer;
}

.cX-Code-Content,
.cX-Code-Content code {
  padding: 0;
  margin: 0;
  font-size: inherit;
  line-height: inherit;
  color: inherit;
  border: none;
}

.cX-Code-Content {
  white-space: pre;
  outline: none;
  cursor: text;
  font-size: small;
  text-align: left;
  word-break: inherit;
  word-wrap: inherit;
  background-color: inherit;
  border-radius: inherit;
  counter-reset: listing;
}

.cX-Code-Content code {
  counter-increment: listing;
  line-height: 1.5;
}

.cX-Code-Content code::before {
  content: counter(listing) " ";
  display: inline-block;
  width: 3em;
  border-right: 1px solid var(--cx-ui-border);
  text-align: right;
  background-color: var(--cx-ui-surface-sunken);
}

