/******************
 * Chat Interface *
 ******************/

.cX-Container-Chat {
  /* was inheriting the host page's font (serif in a bare page) */
  color: var(--cx-ui-text);
  font-family: var(--cx-font-sans);
  height: fit-content;
  opacity: 0;
  visibility: hidden;
  background: var(--cx-ui-surface);
  transition: all var(--cx-transition-speed) ease;
  width: 100%;
  display: none;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: 70px;
  top: var(--base-h);
  left: 0;
