  display: flex;
  width: 100%;
  min-height: 100px;
  background: var(--cx-ui-surface);
  pointer-events: none;
}

.cX-Chat-Text-Area-Container {
  width: calc(100% - 46px);
  padding: 8px;
  box-sizing: border-box;
  position: relative;
  pointer-events: none;
}

.cX-Chat-Messages-Container {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  font-family: var(--cx-font-family);
  overscroll-behavior: contain;
}

.cX-Chat-Messages-Container:has(.cX-Chat-Messages:not(:empty)) {
  border-top: var(--cx-border, 1px solid var(--cx-ui-border-accent));
}

.cX-Chat-Messages {
  display: block;
}

/*
 * Chat HTML Panel — floating, draggable, closable
 */
.cX-Chat-Html-Panel {
  position: fixed;
  width: 500px;
  height: 400px;
  background-color: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  z-index: 10005;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  cursor: move;
  resize: both;
  box-shadow: var(--cx-shadow-2);
}

.cX-Chat-Html-Panel-Header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 6px 10px;
  background: var(--cx-background-color, var(--cx-ui-scrollbar-thumb));
  border-bottom: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  flex-shrink: 0;
  user-select: none;
}

.cX-Chat-Html-Panel-Title {
  font-family: var(--cx-font-family);
  font-size: var(--cx-medium-font-size);
  font-weight: 600;
  color: var(--cx-color-ui-background);
}

img.cX-Chat-Html-Panel-Close,
svg.cX-Chat-Html-Panel-Close {
  cursor: pointer;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  flex-shrink: 0;
}

.cX-Chat-Html-Panel-Content {
  overflow-y: auto;
  padding: 0;
  flex: 1;
  cursor: default;
  overscroll-behavior: contain;
}

/*
 * Chat HTML Panel — LLM response content
 */
.cX-Chat-LLM-Response {
  font-family: var(--cx-font-family);
  font-size: var(--cx-large-font-size);
  line-height: 1.6;
  color: var(--cx-color-ui-font);
  background: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  padding: 16px 20px;
  margin: 10px;
  width: calc(100% - 20px);
  box-sizing: border-box;
}

.cX-Chat-LLM-Response h3 {
  font-size: var(--cx-large-font-size);
  font-weight: 600;
  margin: 0 0 10px;
  color: var(--cx-color-widgets, var(--cx-ui-accent));
  border-bottom: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  padding-bottom: 6px;
}

.cX-Chat-LLM-Response p {
  margin: 6px 0;
}

.cX-Chat-LLM-Response code {
  font-family: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
  font-size: var(--cx-small-font-size);
  background: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  padding: 1px 5px;
  color: var(--cx-color-ui-font);
}

.cX-Chat-LLM-Response pre {
  background: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  padding: 12px 14px;
  overflow-x: auto;
  margin: 10px 0;
}

.cX-Chat-LLM-Response pre code {
  background: none;
  border: none;
  padding: 0;
  color: var(--cx-color-ui-font);
  font-size: var(--cx-small-font-size);
}

.cX-Chat-LLM-Response ul {
  margin: 6px 0 6px 18px;
  padding: 0;
}

.cX-Chat-LLM-Response li {
  margin: 2px 0;
}

.cX-Chat-LLM-Response strong {
  font-weight: 600;
  color: var(--cx-color-ui-font);
}

.cX-Chat-LLM-Response em {
  color: var(--cx-color-gray);
}

.cX-Chat-LLM-Response div {
  margin: 3px 0;
}

.cX-Chat-LLM-Error {
  color: var(--cx-color-red);
  font-weight: 600;
}

.cX-Chat-LLM-Links {
  margin-top: 12px;
  padding-top: 8px;
  border-top: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  font-size: var(--cx-medium-font-size);
}

.cX-Chat-LLM-Links a {
  color: var(--cx-color-widgets, var(--cx-ui-accent));
  text-decoration: none;
}

.cX-Chat-LLM-Links a:hover {
  text-decoration: underline;
}

/*
 * Chat HTML Panel — select_canvasxpress_chart cards
 */
.cX-Chat-Select-Top {
  background: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: 2px solid var(--cx-color-widgets, var(--cx-ui-accent));
  border-radius: var(--cx-border-radius);
  padding: 12px 14px;
  margin-bottom: 10px;
}

.cX-Chat-Select-Alt {
  background: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  padding: 10px 12px;
}

.cX-Chat-Select-Grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  margin-top: 8px;
}

.cX-Chat-Select-Header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 6px;
}

.cX-Chat-Select-GT {
  font-weight: 700;
  font-size: var(--cx-font-size);
  color: var(--cx-color-widgets, var(--cx-ui-accent));
}

.cX-Chat-Select-Score {
  font-size: var(--cx-x-small-font-size);
  color: var(--cx-ui-on-accent);
  background: var(--cx-background-color, var(--cx-ui-scrollbar-thumb));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  padding: 1px 7px;
}

.cX-Chat-Select-Desc {
  font-size: var(--cx-medium-font-size);
  margin: 4px 0;
  color: var(--cx-color-ui-font);
}

.cX-Chat-Select-Clinical {
  font-size: var(--cx-small-font-size);
  margin: 4px 0;
  color: var(--cx-color-gray);
}

.cX-Chat-Select-Factors {
  font-size: var(--cx-small-font-size);
  margin: 4px 0 4px 16px;
