  height: 100%;
  white-space: pre-wrap;
  word-break: break-word;
  pointer-events: auto;
}

.cX-Chat-Question[empty]:empty::before {
  content: attr(data-placeholder);
  color: var(--cx-ui-text-subtle);
}

.cX-Chat-Icon-Container {
  width: 46px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  pointer-events: auto;
}

.cX-Chat-Suggestions-Container {
  display: none;
  padding: 12px 18px 18px 18px;
  border-top: 1px solid var(--cx-ui-border);
  background: var(--cx-ui-surface-sunken);
}

.cX-Chat-Suggestions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-height: 30px;
  max-height: 200px;
  overflow-y: auto;
  padding-bottom: 5px;
}

.cX-Chat-Thumbs-Container {
  width: 100%;
  height: 36px;
  background: var(--cx-ui-surface-sunken);
  border-top: 1px solid var(--cx-ui-border);
  display: none;
  align-items: center;
  padding: 0 10px;
  gap: 12px;
  box-sizing: border-box;
}

.cX-Chat-Output {
  width: 100%;
  max-width: 900px;
  margin-top: 5px;
  min-height: 100px;
  padding: 5px;
  outline: none;
  border: none;
  font-family: monospace;
  font-size: var(--cx-medium-font-size);
  box-sizing: border-box;
  resize: vertical;
  display: none;
}

/*
 * Chat Output Container (Tabs & Content)
 */
div.cX-Chat-Output-Container {
  position: absolute;
  width: calc(var(--base-w) + 18px);
  height: calc(var(--base-h) + 82px);
  background-color: var(--cx-background-widgets-color, var(--cx-ui-surface));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-radius: var(--cx-border-radius);
  z-index: 10005;
  display: none; /* Toggled by JS */
  box-sizing: border-box;
  overflow: hidden;
  cursor: move;
}

/* Close Button */
img.cX-Chat-Output-Close,
svg.cX-Chat-Output-Close {
  position: absolute;
  top: 8px;
  right: 8px;
  cursor: pointer;
  z-index: var(--cx-z-raised);
  background: var(--cx-color-transparent) !important;
  border: none !important;
  box-shadow: 0 0 0px var(--cx-color-transparent) !important;
}

/* Tabs */
button.cX-Chat-Output-Tab {
  display: inline-block;
  vertical-align: bottom;
  background-color: var(--cx-background-hover-color, var(--cx-ui-accent-tint));
  border: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  border-bottom: none;
  padding: 5px 10px;
  margin: 10px 0 0 10px;
  cursor: pointer;
  font: var(--cx-large-font);
  color: var(--cx-font-color, var(--cx-ui-text));
  border-radius: var(--cx-border-radius) var(--cx-border-radius) 0 0;
  outline: none;
  position: relative;
  top: 1px; /* Overlaps the content border to look like a real tab */
  z-index: var(--cx-z-base);
  box-sizing: border-box;
  line-height: 24px;
}

/* Adds a small gap between the first and second tab */
button.cX-Chat-Output-Tab + button.cX-Chat-Output-Tab {
  margin-left: 4px;
}

button.cX-Chat-Output-Tab:hover {
  background-color: var(--cx-background-widgets-color, var(--cx-ui-surface));
}

button.cX-Chat-Output-Tab.Active {
  background-color: var(--cx-background-widgets-color, var(--cx-ui-surface));
  font: var(--cx-large-font-bold);
  border-bottom: 1px solid var(--cx-background-widgets-color, var(--cx-ui-surface));
  z-index: 3;
}

/* "colorful" style: each output tab carries its own accent (top bar + hover +
 * active label), set inline as --cx-item-accent / --cx-item-accent-bg. */
button.cX-Chat-Output-Tab-Accent {
  border-top: 3px solid var(--cx-item-accent) !important;
}
button.cX-Chat-Output-Tab-Accent:hover {
  background-color: var(--cx-item-accent-bg) !important;
}
button.cX-Chat-Output-Tab-Accent.Active {
  color: var(--cx-item-accent) !important;
}

/* Tab Content Containers (Scrollable) */
div.cX-Chat-Graphical-Output,
textarea.cX-Chat-Code-Output {
  display: block;
  clear: both;
  width: 100%;
  height: calc(100% - 46px);
  /* 500px total - 46px for the tabs area */
  border: none;
  border-top: var(--cx-border, 1px solid var(--cx-ui-border-accent));
  background-color: var(--cx-background-widgets-color, var(--cx-ui-surface));
  color: var(--cx-font-color, var(--cx-ui-text));
  overflow: auto;
  /* Enables scrolling for the tab content */
  padding: 10px;
  box-sizing: border-box;
  position: relative;
  z-index: 2;
  margin: 0;
}

.cX-Chat-Graphical-Output {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
  padding-top: 50px;
  /* Pushes the graph div below the absolutely positioned buttons */
  box-sizing: border-box;
}

.cX-Chat-Graphical-Output-Graph {
  width: var(--base-w);
  height: var(--base-h);
  margin-top: 20px;
}

/* Specific styling for the code textarea */
textarea.cX-Chat-Code-Output {
  resize: none;
  outline: none;
  font-family: monospace;
  font-size: var(--cx-large-font-size);
  white-space: pre;
}

