/*
 * CanvasXpress Customizer Right Item Header
 */

.cX-Customizer-RightItemHeader,
.cX-Customizer-RightItemHeaderNB {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
