}

.cX-Customizer-RightItemHeaderNB {
  border-bottom: none !important;
}

.cX-Customizer-RightItemHeaderTop {
  display: flex;
  align-items: center;
  min-height: 18px;
}

.cX-Customizer-RightItemHeaderBottom {
  display: flex;
  align-items: center;
  padding-left: 5px;
  overflow: auto;
  font-size: var(--cx-x-small-font-size);
  color: var(--cx-font-color, var(--cx-ui-text));
}

/*
 * "colorful" style — per-card accent in the right panel. Each card carries its
 * own colour (set inline as --cx-item-accent / --cx-item-accent-bg): a left
 * accent bar plus a tinted, accent-titled header, echoing the MOA cards. The
 * class is only added when dataUIStyle === 'colorful'.
 */
.cX-Customizer-CardAccent {
  border-left: 3px var(--cx-border-style) var(--cx-item-accent) !important;
  border-radius: var(--cx-border-radius);
  overflow: hidden;
}
.cX-Customizer-CardAccent .cX-Customizer-RightItemHeader,
.cX-Customizer-CardAccent .cX-Customizer-RightItemHeaderNB {
  background: var(--cx-item-accent-bg) !important;
  border-bottom-color: var(--cx-item-accent) !important;
}
.cX-Customizer-CardAccent .cX-Customizer-RightItemHeaderTop {
  color: var(--cx-item-accent) !important;
}
/* Standard (non-link) card header title also takes the card's colour. */
.cX-Customizer-CardAccent .cX-Customizer-RightItemHeaderMain > :first-child {
  color: var(--cx-item-accent) !important;
}
/* Hover inside an accented card follows the card's colour, not the global purple. */
.cX-Customizer-CardAccent .cX-Customizer-RightItem:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemLauncher:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemLauncherNB:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemTextArea > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemTextArea > textarea:hover,
.cX-Customizer-CardAccent .cX-Customizer-ContainerRaw > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemCol1 > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemCol2 > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemCol3 > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemCol4 > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemCol5 > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-RightItemCol6 > svg:hover,
.cX-Customizer-CardAccent .cX-Customizer-ListNumeric:hover,
.cX-Customizer-CardAccent .cX-Customizer-ListString:hover,
.cX-Customizer-CardAccent .cX-Customizer-ListUnique:hover {
  background: var(--cx-item-accent-bg) !important;
  background-color: var(--cx-item-accent-bg) !important;
}
/* Selects take only the colour: the background shorthand above would also wipe their chevron. */
.cX-Customizer-CardAccent .cX-Customizer-RightItemSelect > select:hover {
  background-color: var(--cx-item-accent-bg);
}
/* Range sliders inside an accented card follow the card's colour (thumb + fill),
 * not the global purple. -webkit- and -moz- pseudo-elements must stay in separate
 * rules or the whole rule is dropped. */
.cX-Customizer-CardAccent input[type=range]::-webkit-slider-thumb {
  background: var(--cx-item-accent) !important;
}
.cX-Customizer-CardAccent input[type=range]::-moz-range-thumb {
  background: var(--cx-item-accent) !important;
}
.cX-Customizer-CardAccent div.cX-RangeSlider > div.cX-RangeSlider-Range,
.cX-Customizer-CardAccent div.cX-RangeSlider > div.cX-RangeSlider-Thumb-Left,
.cX-Customizer-CardAccent div.cX-RangeSlider > div.cX-RangeSlider-Thumb-Right {
  background-color: var(--cx-item-accent) !important;
}
/* Match the filter treatment: the card's field labels take the card's colour.
 * (Search panel titles included; its inputs/description content stay neutral.) */
.cX-Customizer-CardAccent .cX-Customizer-RightItemComboBottomRight,
.cX-Customizer-CardAccent .cX-Customizer-RightItemLauncherRight,
.cX-Customizer-CardAccent .cX-Customizer-RightItemBottom,
.cX-Customizer-CardAccent .cX-Customizer-SearchSelect,
.cX-Customizer-CardAccent .cX-Customizer-SearchCategory,
.cX-Customizer-CardAccent .cX-Customizer-SearchDescription,
.cX-Customizer-CardAccent .cX-Customizer-SearchCurrent {
  color: var(--cx-item-accent) !important;
}
/* The Search panel's field labels are drawn via ::before/::after pseudo-elements
 * (each with its own colour) — colour those to the card accent too. */
.cX-Customizer-CardAccent .cX-Customizer-SearchSelect:before,
.cX-Customizer-CardAccent .cX-Customizer-SearchSelect:after,
.cX-Customizer-CardAccent .cX-Customizer-SearchCategory:before,
.cX-Customizer-CardAccent .cX-Customizer-SearchCategory:after,
.cX-Customizer-CardAccent .cX-Customizer-SearchDescription:before,
.cX-Customizer-CardAccent .cX-Customizer-SearchDescription:after,
.cX-Customizer-CardAccent .cX-Customizer-SearchCurrent:before,
.cX-Customizer-CardAccent .cX-Customizer-SearchCurrent:after {
  color: var(--cx-item-accent) !important;
}

.cX-Customizer-RightItemHeaderMain {
  grid-area: 1 / 1 / 3 / 2;
  display: flex;
  align-items: center;
}

/*
 * CanvasXpress Customizer Right Item Sub Header
 */

.cX-Customizer-RightItemSubHeaderRow {
  grid-area: 1 / 1 / 2 / 2;
  display: flex;
  align-items: center;
}

.cX-Customizer-RightItemSubHeaderRaw {
  display: flex;
  align-items: center;
  border-radius: var(--cx-border-radius);
  border: 1px var(--cx-border-style) var(--cx-datatable-border-color, var(--cx-ui-border-accent)) !important;
  background-color: var(--cx-background-hover-color, var(--cx-ui-accent-tint));
}

/*
 * CanvasXpress Customizer Right Item Launcher
 */

.cX-Customizer-RightItemLauncher {
  display: grid;
  grid-template-columns: 1fr 6fr;
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  width: 100%;
  box-sizing: border-box;
  border: none !important;
  box-shadow: none !important;
  min-height: 34px;
  background: var(--cx-background-widgets-color, var(--cx-ui-surface));
  overflow: hidden;
}

.cX-Customizer-RightItemLauncher *,
.cX-Customizer-RightItemLauncherNB * {
  pointer-events: none;
}

.cX-Customizer-RightItemLauncherNB > :last-child input:first-child {
  pointer-events: auto;
}

.cX-Customizer-RightItemLauncherNB {
  display: grid;
  grid-template-columns: 1fr 6fr;
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  width: 100%;
  box-sizing: border-box;
  border: none !important;
  box-shadow: none !important;
  overflow: hidden;
}

/* Launcher groups use the wrapper border; rows only get internal separators */
.cX-Customizer-Container > .cX-Customizer-RightItemLauncher + .cX-Customizer-RightItemLauncher,
.cX-Customizer-Container > .cX-Customizer-RightItemLauncherNB + .cX-Customizer-RightItemLauncher,
.cX-Customizer-Container > .cX-Customizer-RightItemLauncher + .cX-Customizer-RightItemLauncherNB,
.cX-Customizer-Container > .cX-Customizer-RightItemLauncherNB + .cX-Customizer-RightItemLauncherNB {
  border-top: 1px solid var(--cx-datatable-banner-border-color, var(--cx-ui-chrome-border)) !important;
}

/* Override inline launcher width so rows do not cover the wrapper right border */
.cX-Customizer-Container > .cX-Customizer-RightItemLauncher,
.cX-Customizer-Container > .cX-Customizer-RightItemLauncherNB {
  width: calc(100% - 2px) !important;
  margin-left: 1px;
  margin-right: 1px;
}

/* Preserve bottom corner rounding on the last launcher row in each section */
.cX-Customizer-Container > .cX-Customizer-RightItemLauncher:last-child,
.cX-Customizer-Container > .cX-Customizer-RightItemLauncherNB:last-child {
  border-bottom-left-radius: 6px;
  border-bottom-right-radius: 6px;
}

.cX-Customizer-RightItemLauncher:hover,
.cX-Customizer-RightItemLauncherNB:hover {
  background-color: var(--cx-customizer-hover-color, var(--cx-ui-accent-tint));
}

.cX-Customizer-RightItemLauncherLeft {
  grid-area: 1 / 1 / 2 / 2;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--cx-customizer-hover-color, var(--cx-ui-accent-tint));
}

.cX-Customizer-RightItemLauncherRight {
  grid-area: 1 / 2 / 2 / 3;
  display: flex;
  align-items: center;
  padding-left: 8px;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
}

/*
 * CanvasXpress Customizer Right Item Cols
 */

.cX-Customizer-RightItemFullCol {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  margin: 3px;
  height: fit-content;
}

.cX-Customizer-RightItemHalfCol {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  margin: 3px;
  height: fit-content;
}

.cX-Customizer-RightItemThirdCol {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  margin: 3px;
  height: fit-content;
}

.cX-Customizer-RightItemFourthCol {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  margin: 3px;
  height: fit-content;
}

.cX-Customizer-RightItemFifthCol {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  margin: 3px;
  height: fit-content;
}

.cX-Customizer-RightItemSixthCol {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  grid-template-rows: 1fr;
  grid-column-gap: 0px;
  grid-row-gap: 0px;
  margin: 3px;
  height: fit-content;
}

.cX-Customizer-RightItemCol1,
.cX-Customizer-RightItemCol2,
.cX-Customizer-RightItemCol3,
.cX-Customizer-RightItemCol4,
.cX-Customizer-RightItemCol5,
.cX-Customizer-RightItemCol6 {
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 1 1 0%;
  min-width: 0;
}

.cX-Customizer-RightItemCol1 {
  grid-area: 1 / 1 / 2 / 2;
}

.cX-Customizer-RightItemCol2 {
  grid-area: 1 / 2 / 2 / 3;
}

.cX-Customizer-RightItemCol3 {
  grid-area: 1 / 3 / 2 / 4;
}

.cX-Customizer-RightItemCol4 {
  grid-area: 1 / 4 / 2 / 5;
}

.cX-Customizer-RightItemCol5 {
  grid-area: 1 / 5 / 2 / 6;
}

.cX-Customizer-RightItemCol6 {
  grid-area: 1 / 6 / 2 / 7;
}

.cX-Customizer-RightItemGrid .cX-Customizer-RightItemColor {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
}

.cX-Customizer-RightItemGrid .cX-Customizer-RightItemColor > .cX-Customizer-RightItemCol1 {
  width: 100%;
}

.cX-Customizer-RightItemGrid .cX-Customizer-RightItemColor input[type="color"] {
  width: 26px !important;
  height: 26px !important;
}

.cX-Customizer-ContainerRaw.cX-Customizer-RightItemText .cX-Customizer-RightItemColor input[type="color"] {
  width: 26px !important;
  height: 26px !important;
}

/*
 * Integer spinner (-, value, +): push the buttons outward into the empty outer columns for more
 * separation from the value box. A transform leaves the box (and its fixed-width input) untouched,
 * and moves the click target with the icon.
 */
.cX-Customizer-RightItemInt .cX-Customizer-RightItemCol2 {
  transform: translateX(-6px);
}

.cX-Customizer-RightItemInt .cX-Customizer-RightItemCol5 {
  transform: translateX(6px);
}

.cX-Customizer-RightItemColMid {
  grid-area: 1 / 3 / 2 / 5;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--cx-border-radius);
  border: 1px var(--cx-border-style) var(--cx-datatable-border-color, var(--cx-ui-border-accent)) !important;
}

.cX-Customizer-RightItemSelect>select,
.cX-Customizer-RightItemTextArea > textarea {
  overflow: hidden;
  resize: none;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  vertical-align: middle;
  padding-top: 0;
  padding-bottom: 0;
  line-height: normal;
}

/*
 * Select boxes draw their own chevron instead of the native arrow: the browser pins that against
 * the right border and padding cannot move it. Two thin diagonals in currentColor form the V, so it
 * follows the text colour in light and dark themes. padding-left keeps the value where the native
 * control put it; padding-right keeps long values clear of the chevron.
 */
.cX-Customizer-RightItemSelect > select {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  padding-left: 4px;
  padding-right: 20px;
  background-image:
    linear-gradient(45deg, transparent 40%, currentColor 40%, currentColor 60%, transparent 60%),
    linear-gradient(-45deg, transparent 40%, currentColor 40%, currentColor 60%, transparent 60%);
  background-position:
    calc(100% - 13px) 50%,
    calc(100% - 8px) 50%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

/* High-contrast (forced colours) mode drops background images: fall back to the native arrow. */
@media (forced-colors: active) {
  .cX-Customizer-RightItemSelect > select {
    -webkit-appearance: auto;
    -moz-appearance: auto;
    appearance: auto;
    background-image: none;
  }
}

.cX-Customizer-RightItemTextArea>svg:hover,
.cX-Customizer-RightItemTextArea>textarea:hover,
.cX-Customizer-ContainerRaw>svg:hover,
.cX-Customizer-RightItemCol1>svg:hover,
.cX-Customizer-RightItemCol2>svg:hover,
.cX-Customizer-RightItemCol3>svg:hover,
.cX-Customizer-RightItemCol4>svg:hover,
.cX-Customizer-RightItemCol5>svg:hover,
.cX-Customizer-RightItemCol6>svg:hover,
.cX-Customizer-RightItem:hover {
  background-color: var(--cx-customizer-hover-color, var(--cx-ui-accent-tint));
}

/*
 * Other Customizer classes
 */

.cX-Customizer-Container {
  height: fit-content;
  border-radius: var(--cx-border-radius);
  margin: 6px;
  float: left;
}

.cX-Customizer-Wrangling {
  height: 204px;
  margin: 0px 0px 10px 10px;
  border-radius: var(--cx-border-radius);
  overflow-y: auto;
  overflow-x: hidden;
}

.cX-Customizer-Numeric,
.cX-Customizer-String,
.cX-Customizer-Unique,
.cX-Customizer-Wrangling,
.cX-Customizer-Container {
  border: 1px var(--cx-border-style) var(--cx-datatable-border-color, var(--cx-ui-border-accent)) !important;
}

.cX-Customizer-Wrangling:hover {
  border: 1px dashed var(--cx-color-red) !important;
}

/***************************************************
/* target items specifically within the customizer *
 * containers for moving in the wrangling          *
 ***************************************************/

.cX-Customizer-Numeric,
.cX-Customizer-String,
.cX-Customizer-Unique,
.cX-Customizer-ListNumeric,
.cX-Customizer-ListString,
.cX-Customizer-ListUnique {
  margin-top: 3px !important;
  display: block;
}

/***************************************************/

.cX-Customizer-ContainerRaw {
  border: none !important;
  float: left;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Keep text+icon group labels compact so long labels don't make items look uneven */
.cX-Customizer-ContainerRaw.cX-Customizer-RightItemTextImagesGroup .cX-Customizer-RightItemBottom {
  font-size: var(--cx-x-small-font-size);
  line-height: 1.05;
}

.cX-Customizer-ContainerRaw.cX-Customizer-RightItemTextImagesGroup .cX-Customizer-RightItemBottom > span:first-child {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}

/* Shelves Filters card: the filter list must drop BELOW the floated funnel
 * slot group (ContainerRaw floats left), not sit top-aligned beside it; its
 * width/margins mirror the RightItemTextImagesGroup clamp so both align. */
.cX-Customizer-ShelfFiltersList {
  clear: both;
  width: calc(100% - 2px);
  margin: 0 1px;
  box-sizing: border-box;
}

/* Inside a Filters-shelf field box the box itself draws the frame — flatten the
   embedded DataFilter widget (border + hover tint + inset search) so the entry
   reads as ONE card instead of nested boxes. */
.cX-Customizer-ShelfFilterField .cX-DataFilter-Container-Hoverable {
  border: none;
  border-radius: 0;
  margin: 0;
}

.cX-Customizer-ShelfFilterField .cX-DataFilter-Container-Hoverable:hover {
  background-color: var(--cx-color-transparent);
}

.cX-Customizer-ShelfFilterField input.cX-DataFilter-Search {
  width: 100%;
  margin-left: 0;
  height: 28px;
}

.cX-Customizer-ShelfFilterField .cX-DataFilter-Container-Mask,
.cX-Customizer-ShelfFilterField .cX-DataFilter-Container-Mask-NoOverflow {
  margin: 5px 0 2px;
}

/* The checklist labels ship at a fixed 220px (wider than the shelf card) and
   are RECREATED on every filter click (refreshDataFilters -> loadStringFilter),
   so the relaxation must live here in CSS, not as build-time inline style —
   inline-only relaxation broke the rows after the first (de)select. */
.cX-Customizer-ShelfFilterField label.cX-Checkbox-Label {
  width: calc(100% - 60px);
}

/* Numeric filter's Log/Lin toggle: the range slider gives the toggle a
   50%-wide top-row cell, too narrow inside the shelf card — 'Lin' wrapped
   onto a clipped second line. Keep the toggle on one line and shrink its
   labels (cf. .cX-Workflow-Settings span.cX-Toggle). */
.cX-Customizer-ShelfFilterField label.cX-Toggle {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
}

.cX-Customizer-ShelfFilterField span.cX-Toggle {
  font-size: var(--cx-x-small-font-size);
  margin-left: 3px;
  margin-right: 3px;
}

.cX-Customizer-Mask {
  background: var(--cx-color-transparent) !important;
  border: 0px none !important;
  box-shadow: 0 0 0px var(--cx-color-transparent) !important;
  position: absolute;
  left: 0px;
  top: 0px;
  margin: 0px !important;
  width: 100%;
  height: 20px;
}

.cX-Customizer-Numeric,
.cX-Customizer-String,
.cX-Customizer-Unique {
  border-radius: var(--cx-border-radius);
  cursor: move;
  margin: 3px;
  padding: 3px;
  word-wrap: normal;
  display: inline-block;
  text-align: start;
  max-width: 150px;
  overflow: hidden;
  position: relative;
}

.cX-Customizer-Numeric {
  color: var(--cx-font-color, var(--cx-ui-text));
  background-color: var(--cx-color-transparent);
}

.cX-Customizer-String {
  color: var(--cx-color-green);
  background-color: var(--cx-color-transparent);
}

.cX-Customizer-Unique {
  color: var(--cx-color-blue);
  background-color: var(--cx-color-transparent);
}
.cX-Customizer-ListNumeric,
.cX-Customizer-ListString,
.cX-Customizer-ListUnique {
  border: none;
  cursor: move;
  margin: 0;
  padding: 0 0 0 3px;
  width: 350px;
  white-space: nowrap;
  display: inline-block;
  text-align: start;
  overflow: hidden;
  position: relative;
  background-color: var(--cx-color-transparent);
}

.cX-Customizer-ListNumeric {
  color: var(--cx-font-color, var(--cx-ui-text));
}

.cX-Customizer-ListString {
  color: var(--cx-color-green);
}

.cX-Customizer-ListUnique {
  color: var(--cx-color-blue);
}

.cX-Customizer-ListNumeric:hover,
.cX-Customizer-ListString:hover,
.cX-Customizer-ListUnique:hover {
  background: var(--cx-customizer-hover-color, var(--cx-ui-accent-tint));
}

.cX-Customizer-ListNumeric:before,
.cX-Customizer-ListString:before,
.cX-Customizer-ListUnique:before {
  font: normal 10px courier;
  color: var(--cx-background-color, var(--cx-ui-scrollbar-thumb));
}

