 var(--cx-font-color, var(--cx-ui-text));\n}\n\nspan.cX-Customizer-SearchDescription,\nspan.cX-Customizer-SearchCategory {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\nspan.cX-Customizer-SearchDescription,\nspan.cX-Customizer-SearchCategory,\nspan.cX-Customizer-SearchCurrent {\n  color: var(--cx-background-color, var(--cx-ui-scrollbar-thumb));\n}\n\nspan.cX-Customizer-SearchSelect:before {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \"Select property (\";\n}\n\nspan.cX-Customizer-SearchSelect:after {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \")\";\n}\n\nspan.cX-Customizer-SearchDescription:before {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \"Description [ \";\n}\n\nspan.cX-Customizer-SearchCategory:before {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \"Category [ \";\n}\n\nspan.cX-Customizer-SearchDescription:after,\nspan.cX-Customizer-SearchCategory:after {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \" ]\";\n}\n\nspan.cX-Customizer-SearchCurrent:before {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \"Current Value [ \";\n}\n\nspan.cX-Customizer-SearchCurrent:after {\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font-weight: bold;\n  content: \" ]\";\n}\n\n/*\n * Password\n */\n\n.cX-Password-Dialog {\n  border-radius: var(--cx-border-radius);\n  background-color: var(--cx-background-widgets-color, var(--cx-ui-surface));\n  box-sizing: border-box;\n  cursor: move;\n  color: var(--cx-font-color, var(--cx-ui-text));\n  font: normal 16px arial, tahoma, sans-serif;\n  margin: 2px 3px;\n  overflow: hidden;\n  padding: 1px 12px;\n  width: 200px;\n  height: 185px;\n  white-space: nowrap;\n  position: relative;\n  text-align: left;\n}\n\n.cX-Password-Icon {\n  background: var(--cx-color